// Lo que manda el Error Trigger cuando otro flujo falla en producción.
// Solo dispara en ejecuciones automáticas (Schedule, webhook, reanudaciones),
// nunca en las que se lanzan a mano desde el editor.

const e = $input.first().json;
const ex = e.execution ?? {};
const wf = e.workflow ?? {};

// Si el error lo lanzó "Stop and Error", el mensaje ya viene armado por el
// flujo: etapa, qué pasó y qué hacer. Si no, es un error que nadie previó.
const previsto = (ex.lastNodeExecuted ?? '') === 'Detener con error';

return [
  {
    json: {
      asunto: (previsto ? '[Fábrica] ' : '[Fábrica · imprevisto] ') + (wf.name ?? 'flujo sin nombre'),
      flujo: wf.name ?? null,
      nodo: ex.lastNodeExecuted ?? null,
      mensaje: ex.error?.message ?? 'sin mensaje',
      enlace: ex.url ?? null,
      modo: ex.mode ?? null,
      previsto,
    },
  },
];
